WITH valid AS (SELECT id, customer_id, device, browser, started_at, country, CONCAT(browser, ' ', country) AS browser_country, LENGTH(device) AS device_length FROM sessions WHERE customer_id IS NOT NULL) SELECT device, country, MAX(started_at) AS last_seen, COUNT(*) FILTER (WHERE country = 'DE') AS de_rows, COUNT(*) FILTER (WHERE country = 'UK') AS uk_rows, ROUND(SUM(device_length) / NULLIF(COUNT(CASE WHEN device = 'mobile' THEN 1 END), 0), 2) AS device_length_per_mobile, COUNT_IF(browser = 'Firefox') AS firefox_events FROM valid GROUP BY device, country HAVING uk_rows < 1 ORDER BY de_rows NULLS LAST
